  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "In patients with cirrhosis, metoclopramide absolute oral bioavailability was 79.0 ± 18.8%, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C04"],
      "claim": "In patients with alcoholic cirrhosis, tolfenamic acid oral bioavailability was about 100% by AUC comparison, supporting F ≥ 20%."
    },
    {
      "card_ids": ["C03"],
      "claim": "In normal subjects, bumetanide absolute oral bioavailability was 80% after a 1 mg oral solution, supporting F ≥ 20%."
    }
  ],
  "confidence": "high",
  "contradictory_card_ids": [],
  "decision_summary": "Cirrhosis-matched evidence shows high absolute oral bioavailability (79% and ~100%), and all other transferred molecules have numeric F values above 20%; therefore predict high.",
  "evidence_gaps": [
    "Cirrhosis-specific evidence is limited to two transferred molecules; other evidence is from healthy or non-cirrhotic populations.",
    "One low bioavailability estimate (C69) is methodologically limited and was not used as affirmative low evidence."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C35", "C04", "C03"],
  "revision_action": "initial",
  "supportive_card_ids": ["C35", "C04", "C03"]
}

